def removeKdigits(num: str, k: int) -> str:
    stack = []
    for d in num:
        while k > 0 and stack and stack[-1] > d:
            stack.pop()
            k -= 1
        stack.append(d)
    while k > 0 and stack:
        stack.pop()
        k -= 1
    res = ''.join(stack).lstrip('0')
    return res if res else '0'

